const body = $input.item.json || {};
const now = new Date();
let year, month;
if (body.year && body.month) {
  year = Number(body.year);
  month = Number(body.month);
} else {
  const d = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  year = d.getFullYear();
  month = d.getMonth() + 1;
}
const start = new Date(year, month - 1, 1);
const end = new Date(year, month, 1);
const reportMonth = `${year}-${String(month).padStart(2, '0')}-01`;
return [{ json: {
  report_month: reportMonth,
  period_start: start.toISOString(),
  period_end: end.toISOString(),
  department_filter: body.department || 'all'
} }];

const period = $('Calculate Report Period').item.json;
const rows = $input.all().map(i => i.json);
if (!rows.length) {
  return [{ json: {
    report_month: period.report_month,
    total_calls: 0,
    empty: true,
    message: 'هیچ تماسی در این بازه ثبت نشده است.'
  } }];
}
const byAgent = {};
const byDept = { sales: [], support: [], mixed: [], unknown: [] };
for (const row of rows) {
  const dept = row.department || 'unknown';
  if (byDept[dept]) byDept[dept].push(row); else byDept.unknown.push(row);
  const key = row.agent_id || row.agent_name || 'unknown';
  if (!byAgent[key]) {
    byAgent[key] = { agent_id: row.agent_id, agent_name: row.agent_name || 'نامشخص', departments: new Set(), calls: 0, purchase_intent_sum: 0, purchase_intent_count: 0, satisfaction_sum: 0, satisfaction_count: 0, agent_quality_sum: 0, agent_quality_count: 0, needs_review_count: 0, high_priority_count: 0 };
  }
  const a = byAgent[key];
  a.calls += 1;
  a.departments.add(dept);
  if (row.purchase_intent_score != null) { a.purchase_intent_sum += row.purchase_intent_score; a.purchase_intent_count += 1; }
  if (row.satisfaction_final_score != null) { a.satisfaction_sum += row.satisfaction_final_score; a.satisfaction_count += 1; }
  if (row.agent_quality_score != null) { a.agent_quality_sum += row.agent_quality_score; a.agent_quality_count += 1; }
  if (row.needs_human_review) a.needs_review_count += 1;
  if (row.ticket_priority === 'high' || row.ticket_priority === 'urgent') a.high_priority_count += 1;
}
const agentStats = Object.values(byAgent).map(a => ({
  agent_id: a.agent_id,
  agent_name: a.agent_name,
  departments: [...a.departments],
  total_calls: a.calls,
  avg_purchase_intent: a.purchase_intent_count ? Math.round(a.purchase_intent_sum / a.purchase_intent_count) : null,
  avg_satisfaction: a.satisfaction_count ? Math.round(a.satisfaction_sum / a.satisfaction_count) : null,
  avg_agent_quality: a.agent_quality_count ? Math.round(a.agent_quality_sum / a.agent_quality_count) : null,
  needs_review_count: a.needs_review_count,
  high_priority_tickets: a.high_priority_count,
  success_score: a.agent_quality_count && a.satisfaction_count ? Math.round((a.agent_quality_sum / a.agent_quality_count + a.satisfaction_sum / a.satisfaction_count) / 2) : null
})).sort((x, y) => (y.success_score || 0) - (x.success_score || 0));
const deptStats = {};
for (const [dept, list] of Object.entries(byDept)) {
  if (!list.length) continue;
  const sat = list.filter(r => r.satisfaction_final_score != null).map(r => r.satisfaction_final_score);
  const qual = list.filter(r => r.agent_quality_score != null).map(r => r.agent_quality_score);
  const intent = list.filter(r => r.purchase_intent_score != null).map(r => r.purchase_intent_score);
  deptStats[dept] = {
    total_calls: list.length,
    avg_satisfaction: sat.length ? Math.round(sat.reduce((a,b)=>a+b,0)/sat.length) : null,
    avg_agent_quality: qual.length ? Math.round(qual.reduce((a,b)=>a+b,0)/qual.length) : null,
    avg_purchase_intent: intent.length ? Math.round(intent.reduce((a,b)=>a+b,0)/intent.length) : null,
    needs_review_count: list.filter(r => r.needs_human_review).length,
    success_rate_percent: sat.length ? Math.round(sat.filter(s => s >= 70).length / sat.length * 100) : null
  };
}
const aggregate = {
  report_month: period.report_month,
  period_start: period.period_start,
  period_end: period.period_end,
  total_calls: rows.length,
  department_stats: deptStats,
  agent_rankings: agentStats,
  top_performers: agentStats.slice(0, 5),
  needs_coaching: agentStats.filter(a => (a.avg_agent_quality || 100) < 60 || (a.avg_satisfaction || 100) < 60).slice(0, 5),
  sample_call_ids: rows.slice(0, 10).map(r => r.call_id)
};
const prompt = `You are Atlas Call Intelligence reporting AI.\nGenerate a monthly executive report in Persian based on this aggregated call data.\nReturn ONLY valid JSON with this structure:\n{\n  "executive_summary": "خلاصه مدیریتی ۳-۵ جمله",\n  "department_insights": { "sales": "...", "support": "...", "mixed": "..." },\n  "top_strengths": [],\n  "critical_issues": [],\n  "recommendations": [],\n  "training_priorities": [],\n  "kpi_highlights": { "best_agent": "", "most_improved_area": "", "biggest_risk": "" }\n}\nAll text values in Persian. Use the numbers provided; do not invent calls.\n\nData:\n${JSON.stringify(aggregate, null, 2)}`;
return [{ json: { aggregate, prompt, report_month: period.report_month } }];

const item = $input.item.json;
if (item.empty) {
  return [{ json: { report: { meta: { report_month: item.report_month, total_calls: 0 }, message: item.message }, report_month: item.report_month, total_calls: 0 } }];
}
const apiUrl = process.env.API_URL || 'http://host.docker.internal:11434/v1/chat/completions';
const apiKey = process.env.API_KEY || '';
const model = process.env.AI_MODEL || 'gpt-4o-mini';
const response = await this.helpers.request({
  method: 'POST',
  uri: apiUrl,
  json: true,
  headers: apiKey ? { Authorization: `Bearer ${apiKey}` } : {},
  body: { model, messages: [{ role: 'user', content: item.prompt }], temperature: 0.2 }
});
return [{ json: { aggregate: item.aggregate, aiResponse: response, report_month: item.report_month } }];

const item = $input.item.json;
const aggregate = item.aggregate;
if (!aggregate) {
  return [{ json: { success: true, report: item.report, report_month: item.report_month, total_calls: 0 } }];
}
let text = '';
const ai = item.aiResponse || {};
if (ai.choices?.[0]?.message?.content) text = ai.choices[0].message.content;
else if (ai.choices?.[0]?.text) text = ai.choices[0].text;
else text = JSON.stringify(ai);
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
let aiSummary;
try { aiSummary = JSON.parse(text); } catch (e) { aiSummary = { executive_summary: text, parse_error: true }; }
const report = {
  meta: {
    report_month: aggregate.report_month,
    generated_at: new Date().toISOString(),
    workflow_version: '1.0.0',
    total_calls: aggregate.total_calls,
    period_start: aggregate.period_start,
    period_end: aggregate.period_end
  },
  department_stats: aggregate.department_stats,
  agent_rankings: aggregate.agent_rankings,
  top_performers: aggregate.top_performers,
  needs_coaching: aggregate.needs_coaching,
  executive: aiSummary
};
const deptLines = Object.entries(aggregate.department_stats || {}).map(([d, s]) => `- ${d}: ${s.total_calls} تماس، رضایت ${s.avg_satisfaction ?? 'N/A'}، کیفیت ${s.avg_agent_quality ?? 'N/A'}`).join('\n');
const agentLines = (aggregate.top_performers || []).map((a, i) => `${i+1}. ${a.agent_name}: امتیاز ${a.success_score ?? 'N/A'}/100 (${a.total_calls} تماس)`).join('\n');
const emailBody = [
  `گزارش ماهانه Atlas Call Intelligence - ${aggregate.report_month}`,
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  aiSummary.executive_summary || '',
  '',
  `کل تماس‌ها: ${aggregate.total_calls}`,
  '',
  'آمار بخش‌ها:',
  deptLines,
  '',
  'برترین پرسنل:',
  agentLines || '-',
  '',
  'توصیه‌ها:',
  ...(aiSummary.recommendations || []).map(r => `- ${r}`)
].join('\n');
return [{ json: {
  success: true,
  report,
  report_month: aggregate.report_month,
  total_calls: aggregate.total_calls,
  report_json: JSON.stringify(report),
  manager_notification: {
    to: process.env.ATLAS_MANAGER_EMAIL || '',
    subject: `[اطلس] گزارش ماهانه تماس‌ها - ${aggregate.report_month}`,
    body: emailBody
  }
} }];
